const sBOXj = document.getElementById('jenis');
const sBpg = document.getElementById('sjPG');
const sBe = document.getElementById('sjESSAY');

sBOXj.addEventListener('change', function() {
    const value = this.value;

    if (value === 'Pilihan Ganda') {
        sBe.disabled = true;
        sBe.value = "Tidak Ada"; // Reset value
        sBe.style.cssText = "background:#F1F5F9;cursor:not-allowed";
    } else if (value === 'Pilihan Ganda dan Essay') {
        sBe.disabled = false;
        sBe.value = "5";
        sBe.style.cssText = "background:#FDFACE;cursor:pointer";
    }
});  


  const kelasOptionsData = {
      "SD": [
        "Kelas 1 - FASE A", "Kelas 2 - FASE A", "Kelas 3 - FASE B", 
        "Kelas 4 - FASE B", "Kelas 5 - FASE C", "Kelas 6 - FASE C"
      ],
      "SMP": [
        "Kelas 7 - FASE D", "Kelas 8 - FASE D", "Kelas 9 - FASE D"
      ],
      "SMA/SMK": [
        "Kelas 10 - FASE E", "Kelas 11 - FASE F", "Kelas 12 - FASE F"
      ]
    };

    // FUNKSI UPDATE ELEMENT DINAMIS KELAS
    function updateKelasOptions() {
      const jenjangVal = document.getElementById('jenjang').value;
      const kelasSelect = document.getElementById('kelas');
      
      kelasSelect.innerHTML = '';
      const options = kelasOptionsData[jenjangVal] || [];

      options.forEach((kelasName, idx) => {
        const opt = document.createElement('option');
        opt.value = kelasName;
        opt.textContent = kelasName;
        // Default pilih kelas pertengahan (misal Kelas 8 untuk SMP, Kelas 4 untuk SD)
        if ((jenjangVal === 'SMP' && kelasName.includes('8')) ||
            (jenjangVal === 'SD' && kelasName.includes('4')) ||
            (jenjangVal === 'SMA/SMK' && kelasName.includes('10'))) {
          opt.selected = true;
        }
        kelasSelect.appendChild(opt);
      });

      pilihJURUSAN();
    }

    function pilihJURUSAN(){
      const jurusan = document.getElementById('tjurusan');
      const jenjang = document.getElementById('jenjang').value;

      if (jenjang === 'SD' || jenjang === 'SMP') {
        jurusan.disabled = true;
        jurusan.value = "";
        jurusan.style.cssText = "background:#F1F5F9;cursor:not-allowed;padding:9px";
      } else if (jenjang === 'SMA/SMK') {
        jurusan.disabled = false;
        jurusan.style.cssText = "background:#FDFACE;cursor:pointer;padding:9px";
      }
    }

function renderMathInDocument() {
  const container = document.getElementById('JTPediaContent');
  if (!container || typeof renderMathInElement === 'undefined') return;

  try {
    renderMathInElement(container, {
      delimiters: [
        { left: '$$', right: '$$', display: true },
        { left: '$', right: '$', display: false },
        { left: '\\(', right: '\\)', display: false },
        { left: '\\[', right: '\\]', display: true }
      ],
      throwOnError: false
    });
  } catch (e) {
    console.error("Gagal rendering KaTeX:", e);
  }
}

// Debounce Math Render saat user mengetik di editor
let mathRenderTimeout = null;
function debouncedRenderMath() {
  clearTimeout(mathRenderTimeout);
  mathRenderTimeout = setTimeout(() => {
    renderMathInDocument();
  }, 1500);
}

// Insert Formula Snippet ke Topik / CP Input atau Editor
function insertFormulaSnippet(snippet) {
  const currentActive = document.activeElement;
  if (currentActive && (currentActive.tagName === 'INPUT' || currentActive.tagName === 'TEXTAREA')) {
    const start = currentActive.selectionStart;
    const end = currentActive.selectionEnd;
    const text = currentActive.value;
    currentActive.value = text.substring(0, start) + ` $${snippet}$ ` + text.substring(end);
    currentActive.focus();
  } else {
    // Insert directly into editor
    const formatted = ` $${snippet}$ `;
    document.execCommand('insertText', false, formatted);
    renderMathInDocument();
  }
  showToast("Rumus disisipkan: " + snippet, "info");
}

// Toast Notification System 
function showToast(message, type = 'info') {
  const container = document.getElementById('toast-container');
  if (!container) return;

  const bgColors = {
    success: 'background-color:#23C55F; color:#ffffff',
    error: 'background-color:#F65327; color:#ffffff',
    warning: 'background-color:#F0EF2E; color:#004386',
    info: 'background-color:#1E4FD8; color:#ffffff'
  };

  const icons = {
    success: 'fa-circle-check',
    error: 'fa-circle-exclamation',
    warning: 'fa-triangle-exclamation',
    info: 'fa-circle-info'
  };

  const toast = document.createElement('div');
  toast.className = 'toast-animate';
  toast.style.cssText = `padding:0.5rem 1rem; border-radius:0.5rem; font-size:0.875rem; box-shadow:0 10px 15px -3px rgba(0,0,0,0.1);${bgColors[type] || bgColors.info}`;
  toast.innerHTML = `
  <i class="fa-solid ${icons[type] || icons.info} style="margin-right:0.5rem; color:#fde68a;"></i> ${message}`;
  
  container.appendChild(toast);
  setTimeout(() => {
    toast.remove();
  }, 5000);
}

// Toggle Visibility API Key
function togglePasswordVisibility(IDa,IDb) {
  const input = document.getElementById(IDa);
  const icon = document.getElementById(IDb);
  if (input.type === 'password') {
    input.type = 'text';
    icon.className = 'fa-solid fa-eye-slash mr-0.5 text-sm';
  } else {
    input.type = 'password';
    icon.className = 'fa-solid fa-eye mr-0.5 text-sm';
  }
}

// Render Markdown to Editor & Process Custom Boxes & Formats
function renderMarkdownToEditor(mdText) {
  if (typeof marked === 'undefined') {
    showToast("Error loading Markdown parser.", "error");
    return;
  }

  let rawHtml = marked.parse(mdText);

  // Transform placeholder syntax to styled custom UI elements
  const styledHtml = rawHtml
    .replace(/\[\s*Ruang Jawaban\s*\]|\(Ruang Jawaban Siswa\)/gi, `<div class="answer-box">Tuliskan jawaban siswa di sini...</div>`)
    .replace(/<blockquote[^>]*>[\s\S]*?\[MATERI\]([\s\S]*?)<\/blockquote>/gi, (match, p1) => {
      return `<div class="materi-box"><h3 style="margin-top:0; color:#0f766e; font-weight:bold;"><i class="fa-solid fa-book-open"></i> RINGKASAN MATERI PEMBELAJARAN</h3>${p1}</div>`;
    })
    .replace(/<blockquote[^>]*>[\s\S]*?\[TUJUAN\]([\s\S]*?)<\/blockquote>/gi, (match, p1) => {
      return `<div class="tujuan-box"><h3 style="margin-top:0; color:#b45309; font-weight:bold;"><i class="fa-solid fa-bullseye"></i> TUJUAN UTAMA PEMBELAJARAN</h3>${p1}</div>`;
    });

  document.getElementById('JTPediaContent').innerHTML = styledHtml;

  // Automatically render LaTeX formulas inside document
  setTimeout(() => {
    renderMathInDocument();
  }, 100);
}
