// Export to Word (.doc)
function exportWord() {
  const mapel = document.getElementById('mapel').value || `${JTPediaAPP}`;
const topik = document.getElementById('topik').value || 'TOPIK';
  const content = document.getElementById('JTPediaContent').innerHTML;

  const header = `<html xmlns:o='urn:schemas-microsoft-microsoft-com:office:office' ` +
                 `xmlns:w='urn:schemas-microsoft-microsoft-com:office:word' ` +
                 `xmlns='http://www.w3.org/TR/REC-html40'>` +
                 `<head><meta charset='utf-8'><title>JTPedia - ${JTPediaAPP}</title>` +
                 `<style>` +
                 `body { font-family: Arial, sans-serif; font-size: 11pt; line-height: 1.5; padding: 20px; }` +
                 `h1 { font-size: 16pt; color: #0f766e; text-align: center; font-weight: bold; }` +
                 `h2 { font-size: 12pt; color: #115e59; border-bottom: 2px solid #0d9488; margin-top: 15px; }` +
                 `table { width: 100%; border-collapse: collapse; margin-top: 10px; }` +
                 `td, th { border: 1px solid #cbd5e1; padding: 6px; }` +
                 `.answer-box { border: 1px dashed #94a3b8; background-color: #f8fafc; padding: 10px; min-height: 60px; margin-top: 5px; }` +
                 `.materi-box { border: 1px solid #0d9488; background-color: #f0fdfa; padding: 12px; margin-bottom: 12px; }` +
                 `.tujuan-box { border: 1px solid #f59e0b; background-color: #fffbeb; padding: 12px; margin-bottom: 12px; }` +
                 `</style></head><body>`;
  const footer = `</body></html>`;
  const sourceHTML = header + content + footer;

  const blob = new Blob(['\ufeff', sourceHTML], { type: 'application/msword' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `JTPedia${JTPediaAPP.replace(/\s+/g, '_')}_${mapel.replace(/\s+/g, '_')}_${topik.replace(/\s+/g, '_')}.doc`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  showToast("Mengunduh dokumen Word (.doc)...", "info");
}

// Export to PDF (.pdf)
function exportPDF() {
  const mapel = document.getElementById('mapel').value || `${JTPediaAPP}`;
const topik = document.getElementById('topik').value || 'TOPIK';
  const element = document.getElementById('JTPediaContent');
  
  if (typeof html2pdf === 'undefined') {
    showToast("Library PDF belum siap, coba beberapa saat lagi.", "error");
    return;
  }

  showToast("Menyiapkan dokumen PDF...", "info");

  const opt = {
    margin:       [10, 10, 10, 10],
    filename:     `JTPedia${JTPediaAPP.replace(/\s+/g, '_')}_${mapel.replace(/\s+/g, '_')}_${topik.replace(/\s+/g, '_')}.pdf`,
    image:        { type: 'jpeg', quality: 0.98 },
    html2canvas:  { scale: 2, useCORS: true, logging: false },
    jsPDF:        { unit: 'mm', format: 'a4', orientation: 'portrait' },
    pagebreak:    { 
      mode: ['css', 'legacy'], 
      avoid: ['.materi-box', '.tujuan-box', '.answer-box', 'table', 'tr', 'h2', 'h3'] 
    }
  };

  html2pdf().set(opt).from(element).save().then(() => {
    showToast("PDF berhasil diunduh!", "success");
  }).catch(err => {
    showToast("Gagal membuat PDF: " + err.message, "error");
  });
}

//Print Document
function cetakDokumen() {
const mapel = document.getElementById('mapel').value || `${JTPediaAPP}`;
const topik = document.getElementById('topik').value || 'TOPIK';	
const mytitle = `JTPedia${JTPediaAPP.replace(/\s+/g, '_')}_${mapel.replace(/\s+/g, '_')}_${topik.replace(/\s+/g, '_')}`;
document.title = mytitle;	  
window.print();      
}

window.addEventListener('afterprint', () => {
document.title = `JTPEDIA ${JTPediaAPP} - AI Generator & Builder Otomatis dan Dinamis`; 
});

// Helper untuk membuat File & Blob HTML Standalone
function getLKPDHTMLFile() {
  const mapel = document.getElementById('mapel').value || `${JTPediaAPP}`;
  const topik = document.getElementById('topik').value || 'TOPIK';
  const fileName = `JTPedia${JTPediaAPP.replace(/\s+/g, '_')}_${mapel.replace(/\s+/g, '_')}_${topik.replace(/\s+/g, '_')}.html`;
  const content = document.getElementById('JTPediaContent').innerHTML;

  const htmlDoc = `<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>JTPedia: ${JTPediaAPP} - ${mapel} - ${topik}</title>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/katex@0.16.8/dist/katex.min.css">
<script src="https://cdn.jsdelivr.net/npm/katex@0.16.8/dist/contrib/auto-render.min.js"><\/script>
<style>
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');
body { font-family: 'Plus Jakarta Sans', sans-serif; background-color: #f1f5f9; padding: 2rem 1rem; }
.document-paper {
  background-color: #ffffff;
  min-height: 297mm;
  width: 100%;
  max-width: 210mm;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.1);
  border: 1px solid #e2e8f0;
  padding: 2.5rem;
  margin: 0 auto;
  border-radius: 0.5rem;
}

.document-paper h1 { font-size: 1.5rem; font-weight: 700; color: #0f766e; text-align: center; margin-bottom: 0.5rem; }
.document-paper h2 { font-size: 1.15rem; font-weight: 700; color: #115e59; border-bottom: 2px solid #0d9488; padding-bottom: 0.25rem; margin-top: 1.25rem; margin-bottom: 0.75rem; }
.document-paper h3 { font-size: 1rem; font-weight: 600; color: #134e4a; margin-top: 1rem; margin-bottom: 0.5rem; }
.document-paper p, .document-paper li { font-size: 0.92rem; color: #334155; line-height: 1.6; }
.document-paper .pKU {margin-top: -10px; }
.document-paper ul, .document-paper ol { padding-left: 1.25rem; margin-bottom: 0.75rem; }
.document-paper ul { list-style-type: disc; }
.document-paper ol { list-style-type: decimal; }
.document-paper li {font-size: 0.92rem; font-weight: 400}
.jtpediaJAWAB {font-size: 0.85rem}
.jtpediaFONT li {font-size: 0.85rem; font-weight: 500}

.answer-box { border: 1.5px dashed #94a3b8; background-color: #f8fafc; border-radius: 0.5rem; padding: 0.85rem; min-height: 80px; margin-top: 0.5rem; margin-bottom: 0.85rem; color: #64748b; font-style: italic; }
.materi-box { border: 1px solid #99f6e4; background-color: #f0fdfa; border-left: 5px solid #0d9488; border-radius: 0.5rem; padding: 1rem 1.25rem; margin-bottom: 1.25rem; }
.tujuan-box { border: 1px solid #fde68a; background-color: #fffbeb; border-left: 5px solid #f59e0b; border-radius: 0.5rem; padding: 1rem 1.25rem; margin-bottom: 1.25rem; }
@media print {
  body { background: white; padding: 0; }
  .document-paper { box-shadow: none; border: none; padding: 0; width: 100%; max-width: 100%; }
  @page { size: A4 portrait; margin: 15mm; }
}
</style>
</head>
<body>
<div class="document-paper">
${content}
</div>
<script>
window.onload = function() {
  if (typeof renderMathInElement !== 'undefined') {
    renderMathInElement(document.body, {
      delimiters: [
        { left: '$$', right: '$$', display: true },
        { left: '$', right: '$', display: false },
        { left: '\\(', right: '\\)', display: false },
        { left: '\\[', right: '\\]', display: true }
      ],
      throwOnError: false
    });
  }
};
<\/script>
</body>
</html>`;

  const blob = new Blob([htmlDoc], { type: 'text/html;charset=utf-8;' });
  const file = new File([blob], fileName, { type: 'text/html' });
  return { file, blob, fileName };
}

// ceckMyPrompt
const checkbox = document.getElementById('CmyPrompt');
const textarea = document.getElementById('myPrompt');

checkbox.addEventListener('change', function() {
textarea.disabled = !this.checked;
});

// Export to HTML Standalone (.html)
function exportHTML() {
  const { blob, fileName } = getLKPDHTMLFile();
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = fileName;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  showToast("Dokumen HTML mandiri berhasil diunduh!", "success");
}

