const SLIDERwrapper=document.getElementById('sliderWrapper');const slides=document.querySelectorAll('.slide');const dotsContainer=document.getElementById('dotsContainer');let currentIndex=0;const totalSlides=slides.length;slides.forEach((_,index)=>{const dot=document.createElement('div');dot.classList.add('dot');if(index===0)dot.classList.add('active');dot.addEventListener('click',()=> goToSlide(index));dotsContainer.appendChild(dot);});const dots=document.querySelectorAll('.dot');function updateSlider(){SLIDERwrapper.style.transform=`translateX(-${currentIndex*100}%)`;dots.forEach((dot,index)=>{dot.classList.toggle('active',index===currentIndex);});}function goToSlide(index){currentIndex=index;updateSlider();}function nextSlide(){currentIndex=(currentIndex+1)% totalSlides;updateSlider();}function prevSlide(){currentIndex=(currentIndex-1+totalSlides)% totalSlides;updateSlider();}document.addEventListener('DOMContentLoaded',()=>{const SLIDERprevBtn=document.getElementById('prevBtn');const SLIDERnextBtn=document.getElementById('nextBtn');SLIDERnextBtn.addEventListener('click',nextSlide);SLIDERprevBtn.addEventListener('click',prevSlide);});let autoPlay=setInterval(nextSlide,4000);const SILDERcontainer=document.querySelector('.slider-container');SILDERcontainer.addEventListener('mouseenter',()=> clearInterval(autoPlay));SILDERcontainer.addEventListener('mouseleave',()=>{autoPlay=setInterval(nextSlide,4000);});document.addEventListener('DOMContentLoaded',function(){const navContainer=document.getElementById('nav-links-container');const mobileBtn=document.getElementById('mobile-menu-btn');if(mobileBtn && navContainer){mobileBtn.addEventListener('click',function(){navContainer.classList.toggle('active');});}const navLinks=document.querySelectorAll('.nav-links-right a');navLinks.forEach(function(link){link.addEventListener('click',function(){if(window.innerWidth >=200 && navContainer){navContainer.classList.remove('active');}});});window.addEventListener('click',function(event){if(navContainer && mobileBtn){if(!navContainer.contains(event.target)&& !mobileBtn.contains(event.target)){navContainer.classList.remove('active');}}});});window.addEventListener('DOMContentLoaded',()=>{const opsi={day:'numeric',month:'long',year:'numeric'};const tanggal=new Date().toLocaleDateString('id-ID',opsi);document.getElementById('tanggal-indo').textContent=tanggal;})
